// Generated by generators/guests from app/specs/guests (GU-01): the standalone
// guests of PrismMessage, PrismMessage, built by tools/guests/build.sh from the modules the
// Prism compiles, so the Node suites run every request without the holo. Each
// exports holo_alloc(len) and holo_run(ptr, len) -> (outPtr << 32 | outLen);
// bytes whose SHA-256 is not the pinned one are refused before they compile.

export const GUESTS = {
  rules: { path: 'guest/message.wasm', sha256: 'ac7c15750106d23bf6f3ccf0f2ea0be62e9c21fad2b1e31c5d67987ff4ee0513' },
  message: { path: 'guest/message.wasm', sha256: 'ac7c15750106d23bf6f3ccf0f2ea0be62e9c21fad2b1e31c5d67987ff4ee0513' },
};

const hex = (u8) => Array.from(u8, (b) => b.toString(16).padStart(2, '0')).join('');
const encoder = new TextEncoder();
const decoder = new TextDecoder('utf-8', { fatal: true });

async function compile(bytes, sha256) {
  const got = hex(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)));
  if (got !== sha256) throw Object.assign(new Error(`guest refused: fingerprint ${got} is not ${sha256}`), { code: 'message.guest' });
  return WebAssembly.compile(bytes);
}

function run(x, line) {
  const input = encoder.encode(line);
  const ptr = x.holo_alloc(input.length);
  new Uint8Array(x.memory.buffer, ptr, input.length).set(input);
  const packed = BigInt.asUintN(64, BigInt(x.holo_run(ptr, input.length)));
  return decoder.decode(new Uint8Array(x.memory.buffer, Number(packed >> 32n), Number(packed & 0xffffffffn)));
}

// A fresh instance per request: the guest's allocator never frees, and no state carries over.
export async function openGuest(bytes, sha256) {
  const module = await compile(bytes, sha256);
  return async (line) => run((await WebAssembly.instantiate(module, {})).exports, line);
}

// The same, answered synchronously once the one asynchronous step (check and
// compile) is done, by one instance kept and put back as it began before each
// request: its memory above the stack as first instantiated, and what it grew
// by zero. An instance a request trapped is dropped. So no state carries over,
// and reading thousands of fields does not leave thousands of instances.
export async function openGuestSync(bytes, sha256) {
  const module = await compile(bytes, sha256);
  let x = null, first = null, from = 0;
  return (line) => {
    if (x) { const memory = new Uint8Array(x.memory.buffer); memory.set(first, from); memory.fill(0, from + first.length); }
    else { x = new WebAssembly.Instance(module, {}).exports; from = Number(x.__stack_high?.value ?? 0); first = new Uint8Array(x.memory.buffer).slice(from); }
    try { return run(x, line); } catch (error) { x = null; throw error; }
  };
}
